//! Full original base-vars fold over borrowed workspace originals and native declarations.
//! This data producer grants no source/completion; the host retains actual EOF proofs.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::Config,reactive_raw_policy_pages::RawPolicyPages,captured_allow_annotations::Operation,key_policy_control::{self as kc,Control},lint::{Site,AllowUse},base_var_candidate_policy as candidate,base_var_hot_policy as hot};
use std::{collections::{BTreeMap,HashSet},io,path::Path,sync::Arc};
impl From<dm_analysis::untyped::Unsupported> for Failure{fn from(error:dm_analysis::untyped::Unsupported)->Self{Self::Unsupported(error.0)}}
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}check(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
/// Genuine source bytes/lines remain host-owned loans; arbitrary providers cannot seal EOF.
pub trait BaseVarPages:RawPolicyPages{
 fn with_record_line(&self,member:dm_tree::MemberId,visit:&mut dyn FnMut(&str,usize,&str)->Result<(),Failure>)->Result<(),Failure>;
 fn with_fixed_configuration_line(&self,visit:&mut dyn FnMut(&str)->Result<(),Failure>)->Result<(),Failure>;
}
struct Declarations<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>}
impl dm_analysis::base_var_declarations::DeclarationWork for Declarations<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{check(self.budget,self.poll)}fn reserve(&mut self,bytes:usize)->Result<(),Failure>{self.budget.charge(bytes).map_err(|m|oom(self.budget,m))}fn overflow(&mut self)->Failure{oom(self.budget,"base-vars native declaration geometry overflow")}fn allocation_failed(&mut self)->Failure{oom(self.budget,"base-vars native declaration allocation refused")}}
pub struct BaseVarsData{sites:Vec<Site>,source_text:Vec<String>,allows:Vec<AllowUse>,digests:BTreeMap<String,[u8;20]>,notes:Vec<String>}
impl BaseVarsData{
 pub fn metadata(&self)->&'static crate::lint::Meta{&crate::base_var_metadata::META}
 pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allows}pub fn notes(&self)->&[String]{&self.notes}pub fn allow_source_digest(&self,relative:&str)->Option<&[u8;20]>{self.digests.get(relative)}
 pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(5)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.source_text)?;rows.serialize_element(&self.allows)?;rows.serialize_element(&self.digests)?;rows.serialize_element(&self.notes)?;rows.end()}
 pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allows.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for s in &self.sites{for word in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(word.capacity())?}}for word in &self.source_text{n=n.checked_add(word.capacity())?}for a in &self.allows{for word in [&a.rel,&a.name,&a.code]{n=n.checked_add(word.capacity())?}}n=n.checked_add(self.notes.capacity().checked_mul(std::mem::size_of::<String>())?)?;for note in &self.notes{n=n.checked_add(note.capacity())?}for path in self.digests.keys(){n=n.checked_add(2048)?.checked_add(path.capacity())?}Some(n)}
}
pub fn metadata()->&'static crate::lint::Meta{&crate::base_var_metadata::META}

pub fn selects_path(relative:&str)->bool{relative.starts_with("code/")&&relative.ends_with(".dm")}

struct Variable<'a>{native:dm_analysis::base_var_declarations::BaseVarDeclaration<'a>,relative:String,line:u32,owner:&'a str,name:&'a str}
fn variables<'a>(inputs:&'a dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<Vec<Variable<'a>>,Failure>{
 let mut native=Declarations{budget,poll};let rows=dm_analysis::base_var_declarations::base_var_declarations_using(inputs.archive(),hot::BASE_TYPES,root_path,&mut native)?;let tree=inputs.archive().tree();let mut work=Operation{budget,poll};let mut out=Vec::new();for row in rows{work.checkpoint()?;let original=inputs.file_exact(row.source.path.as_path()).ok_or("base-vars declaration has no current captured source")?;if !original.is_compiled(){return Err("base-vars declaration is not actual compiled source".into())}let cursor=inputs.archive().member_policy_compatibility_cursor(row.declaration)?;kc::reserve(&mut work,||cursor.path.as_os_str().len().checked_add(root_path.as_os_str().len())?.checked_mul(128)?.checked_add(4096))?;let relative=dm_preprocess::regions::relative_filesystem_path(cursor.path.as_path(),root_path).as_deref().unwrap_or(cursor.path.as_path()).to_string_lossy().replace('\\',"/");let relative=crate::util::normalize_dots(&relative);let line=if relative.starts_with("code/"){let current=inputs.file_exact(cursor.path.as_path()).ok_or("base-vars code cursor has no current source")?;if !current.is_compiled(){return Err("base-vars code cursor is not actual compiled source".into())}current.analyze_display_line(cursor.line).map_err(|error|Failure::Unsupported(error.to_string()))?}else{cursor.line};if line==0{return Err("base-vars original cursor line is absent".into())}let owner=tree.symbols().text(row.owner).ok_or("base-vars actual owner unavailable")?;let name=tree.symbols().text(row.name).ok_or("base-vars actual variable unavailable")?;kc::row(&mut work,&mut out)?;out.push(Variable{native:row,relative,line:u32::try_from(line).map_err(|_|oom(budget,"base-vars cursor line overflow"))?,owner,name});}
 let mut error=None;out.sort_by(|a,b|{if error.is_none(){if let Err(actual)=work.checkpoint(){error=Some(actual)}}(a.relative.as_str(),a.line,a.owner).cmp(&(b.relative.as_str(),b.line,b.owner))});if let Some(actual)=error{return Err(actual)}Ok(out)
}
fn kept(data:&mut BaseVarsData,file:&crate::tree::SourceFile,line:usize,name:&'static str,local:&Budget,keep:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<bool,Failure>{let raw=file.raw();let mut work=Operation{budget:local,poll};let mut found=None;for at in[Some(line),line.checked_sub(1).filter(|n|*n!=0)].into_iter().flatten(){work.checkpoint()?;if at==0||at>raw.num_lines(){continue}if at!=line&&!crate::util::py_lstrip(raw.line(at)).starts_with("//"){continue}if let Some(code)=crate::allow::keeps_with(raw.line(at),name,&mut work)?{found=Some((at,code.unwrap_or_default()));break}}let Some((at,code))=found else{return Ok(false)};let mut held=Operation{budget:keep,poll};let mut already=false;for used in &data.allows{held.checkpoint()?;if used.rel==file.rel&&used.line as usize==at&&used.name==name&&used.code==code{already=true;break}}if !already{kc::row(&mut held,&mut data.allows)?;keep.charge(code.capacity()).map_err(|m|oom(keep,m))?;data.allows.push(AllowUse{rel:kc::own(&mut held,&file.rel)?,line:u32::try_from(at).map_err(|_|oom(keep,"base-vars ALLOW line overflow"))?,name:kc::own(&mut held,name)?,code})}if !data.digests.contains_key(&file.rel){kc::reserve(&mut held,||Some(2048))?;data.digests.insert(kc::own(&mut held,&file.rel)?,crate::captured_raw_file::source_allow_digest(file));}Ok(true)}
fn site(data:&mut BaseVarsData,rule:&'static str,relative:&str,line:u32,message:String,identity:String,text:&str,budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{let mut work=Operation{budget,poll};work.checkpoint()?;budget.charge(message.capacity().checked_add(identity.capacity()).ok_or_else(||oom(budget,"base-vars report message overflow"))?).map_err(|m|oom(budget,m))?;kc::row(&mut work,&mut data.sites)?;data.sites.push(Site{rule:kc::own(&mut work,rule)?,rel:kc::own(&mut work,relative)?,line,msg:message,key:String::new(),ident:identity});kc::row(&mut work,&mut data.source_text)?;kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;data.source_text.push(crate::util::normalize_ws(text));Ok(())}
fn hint_charge(hints:&crate::value_schema_policy::SchemaHints)->Option<usize>{let mut bytes=Some(0usize);hints.visit_storage(|rows|{bytes=rows.len().checked_mul(2048).and_then(|n|rows.iter().try_fold(n,|n,(owner,name)|n.checked_add(owner.capacity())?.checked_add(name.capacity())))});bytes}
pub fn collect_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn BaseVarPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<BaseVarsData,Failure>{
 check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let pending=(||{let empty=crate::scopes::LintScope::default();let scope=config.borrowed_report_scope("base_vars","").unwrap_or(&empty);let mut work=Operation{budget,poll};let mut data=BaseVarsData{sites:Vec::new(),source_text:Vec::new(),allows:Vec::new(),digests:BTreeMap::new(),notes:Vec::new()};let hot_table=scope.table(hot::HOT_TABLE);let empty_hot=BTreeMap::new();let hot_table=hot_table.unwrap_or(&empty_hot);kc::row(&mut work,&mut data.notes)?;data.notes.push(kc::format(&mut work,format_args!("base_vars: {} hot base vars homed by base_var_home_hot",hot_table.len()))?);let mut homes=HashSet::new();let mut singletons=HashSet::new();let mut hints=crate::value_schema_policy::SchemaHints::default();let mut hints_held=0;
 let facts=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("base-vars facts escaped hidden-inclusive CODE".into())}views.code()?;let file=views.source_file()?;let mut temp=Operation{budget:local,poll};let facts=candidate::file_facts_using(file,scope.list("base_var_home_macros"),scope.list("base_var_home_relations"),&mut temp)?;for(owner,name)in facts.homes{work.checkpoint()?;kc::reserve(&mut temp,||owner.len().checked_add(name.len())?.checked_mul(8)?.checked_add(256))?;if !homes.contains(&(owner.clone(),name.clone())){kc::reserve(&mut work,||owner.capacity().checked_add(name.capacity())?.checked_add(2048))?;homes.insert((owner,name));}}for owner in facts.singles{work.checkpoint()?;if owner!="/datum"&&!singletons.contains(&owner){kc::reserve(&mut work,||owner.capacity().checked_add(2048))?;singletons.insert(owner);}}for line in candidate::raw_allow_lines_using(file,&mut temp)?{kept(&mut data,file,line,"base_vars",local,budget,poll)?;}if !file.hidden{views.marker()?;hints.read_with_control(file,&mut temp)?;let actual=hint_charge(&hints).ok_or_else(||oom(budget,"base-vars retained schema hint overflow"))?;if actual>hints_held{budget.charge(actual-hints_held).map_err(|m|oom(budget,m))?;hints_held=actual;}}Ok(true)})();finish(pending,local,poll)})?;if !facts{return Err("base-vars hidden CODE facts omitted actual EOF".into())}
 let rows=variables(inputs,root_path,budget,poll)?;let mut declared=HashSet::new();for row in &rows{work.checkpoint()?;if row.native.base{kc::reserve(&mut work,||Some(2048))?;declared.insert((kc::own(&mut work,row.owner)?,kc::own(&mut work,row.name)?));}}
 let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("base-vars judgment escaped hidden-inclusive CODE".into())}let file=views.source_file()?;if file.hidden{return Ok(true)}let mut temp=Operation{budget:local,poll};for row in &rows{temp.checkpoint()?;if row.relative!=relative{continue}let mut width=0usize;for id in[row.native.metadata.declared_type,row.native.metadata.list_element_type,row.native.metadata.array.as_ref().and_then(|array|array.element_type)].into_iter().flatten(){temp.checkpoint()?;let text=inputs.archive().tree().symbols().text(id).ok_or("base-vars actual declared type spelling absent")?;width=width.checked_add(text.len()).ok_or_else(||oom(local,"base-vars type spelling overflow"))?;}kc::reserve(&mut temp,||width.checked_mul(8)?.checked_add(1024))?;let vtype=row.native.declared_type_text()?;let view=candidate::VarView{rel:relative,line:row.line,owner:row.owner,name:row.name,vtype:&vtype,base:row.native.base,list_init:row.native.list_init};let Some(result)=candidate::classify_using(view,&singletons,scope.list("list_init_exempt_prefixes"),scope.list("list_init_exempt_files"),&homes,hot_table,scope.list("base_var_home_types"),&mut temp,&mut|name,line,_|kept(&mut data,file,line,name,local,budget,poll))?else{continue};let identity=kc::format(&mut temp,format_args!("{}::{}",row.owner,row.name))?;if result.base{let message=if hints.has_with_control(row.owner,row.name,&mut temp)?{crate::value_schema_policy::hint_message_with_control(&identity,&mut temp)?}else{String::new()};site(&mut data,"base_var",relative,row.line,message,kc::own(&mut temp,&identity)?,file.raw().line(row.line as usize),budget,poll)?;}if result.list{site(&mut data,"list_init",relative,row.line,String::new(),identity,file.raw().line(row.line as usize),budget,poll)?;}}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("base-vars judgment omitted actual hidden CODE EOF".into())}
 let ceiling=scope.list("hot_ceiling").first().and_then(|word|word.trim().parse().ok());let problems=hot::hot_problems_using(hot_table,Some(&declared),&homes,ceiling,&mut work)?;if !problems.is_empty(){pages.with_fixed_configuration_line(&mut|text|{for(key,message)in problems.iter(){work.checkpoint()?;site(&mut data,"hot_home",hot::SCOPES_FILE,1,kc::own(&mut work,message)?,kc::format(&mut work,format_args!("hot::{key}"))?,text,budget,poll)?;}Ok(())})?;}
 let mut native=Declarations{budget,poll};for row in dm_analysis::base_var_declarations::record_procedures_using(inputs.archive(),root_path,&mut native)?{work.checkpoint()?;let name=inputs.archive().tree().symbols().text(row.name).ok_or("base-vars record callable spelling absent")?;let mut accessor=false;for prefix in scope.list("record_accessor_prefixes"){work.checkpoint()?;if name.starts_with(prefix.as_str()){accessor=true;break}}if accessor{continue}pages.with_record_line(row.member,&mut|relative,line,text|site(&mut data,"records_data_only",relative,u32::try_from(line).map_err(|_|oom(budget,"record policy line overflow"))?,String::new(),String::new(),text,budget,poll))?;}check(budget,poll)?;Ok(data)})();let pending=finish(pending,budget,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"base-vars report backing overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)
}
